"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["62857"],{53241(e,a,i){i.r(a),i.d(a,{metadata:()=>n,default:()=>h,frontMatter:()=>r,contentTitle:()=>c,toc:()=>l,assets:()=>o});var n=JSON.parse('{"id":"nhcx/v1/concepts/pmjay-scheme-rules","title":"PMJAY scheme rules","description":"The scheme rules that change what goes in a bundle: unspecified, cyclic, medical, newborn, implant and stratification cases.","source":"@site/docs/nhcx/v1/concepts/pmjay-scheme-rules.md","sourceDirName":"nhcx/v1/concepts","slug":"/nhcx/v1/concepts/pmjay-scheme-rules","permalink":"/docs/pr-9/docs/nhcx/v1/concepts/pmjay-scheme-rules","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1788935836000,"sidebarPosition":7,"frontMatter":{"title":"PMJAY scheme rules","sidebar_label":"PMJAY scheme rules","description":"The scheme rules that change what goes in a bundle: unspecified, cyclic, medical, newborn, implant and stratification cases.","verification":"unverified","source":"NHCX FAQs v1.2 \xa724 to \xa729; NHCX PMJAY Integration Handbook \xa76.6; Insurance Plan Implementation Guide; Standard Error Codes, Preauth PAYR-1259 to 1273","sidebar_position":7},"sidebar":"nhcx-v1-overview","previous":{"title":"PMJAY on NHCX","permalink":"/docs/pr-9/docs/nhcx/v1/concepts/pmjay-on-nhcx"},"next":{"title":"Building a provider","permalink":"/docs/pr-9/docs/nhcx/v1/building-a-provider/"}}'),t=i(62540),s=i(43023);let r={title:"PMJAY scheme rules",sidebar_label:"PMJAY scheme rules",description:"The scheme rules that change what goes in a bundle: unspecified, cyclic, medical, newborn, implant and stratification cases.",verification:"unverified",source:"NHCX FAQs v1.2 \xa724 to \xa729; NHCX PMJAY Integration Handbook \xa76.6; Insurance Plan Implementation Guide; Standard Error Codes, Preauth PAYR-1259 to 1273",sidebar_position:7},c="PMJAY scheme rules",o={},l=[{value:"In short",id:"in-short",level:2},{value:"Unspecified procedures",id:"unspecified-procedures",level:2},{value:"Cyclic procedures",id:"cyclic-procedures",level:2},{value:"Medical packages",id:"medical-packages",level:2},{value:"Newborns and children up to six",id:"newborns-and-children-up-to-six",level:2},{value:"Implants and stratification",id:"implants-and-stratification",level:2}];function d(e){let a={code:"code",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(a.header,{children:(0,t.jsx)(a.h1,{id:"pmjay-scheme-rules",children:"PMJAY scheme rules"})}),"\n",(0,t.jsx)(a.p,{children:"The exchanges in the previous chapter are the same for every PMJAY case. What varies is the case. The scheme has a handful of rules that change what goes into a bundle, and a hospital system has to recognise each situation before it builds one."}),"\n",(0,t.jsx)(a.h2,{id:"in-short",children:"In short"}),"\n",(0,t.jsxs)(a.ul,{children:["\n",(0,t.jsx)(a.li,{children:"The exchanges are the same for every case. What varies is the case."}),"\n",(0,t.jsx)(a.li,{children:"Five situations change what goes in a bundle: unspecified, cyclic, medical, newborn, and implant or stratification."}),"\n",(0,t.jsx)(a.li,{children:"An unspecified procedure is always planned, always a single line item, and always validated on the server."}),"\n",(0,t.jsx)(a.li,{children:"A cyclic procedure needs live biometrics at every visit, and pays only for the cycles captured."}),"\n"]}),"\n",(0,t.jsx)(a.h2,{id:"unspecified-procedures",children:"Unspecified procedures"}),"\n",(0,t.jsx)(a.p,{children:"Sometimes a patient needs something the package list does not name. The scheme allows it, under conditions."}),"\n",(0,t.jsxs)(a.p,{children:['The plan marks each package with an "unspecified" flag. Every specialty has one unspecified package, coded as the specialty\'s prefix followed by 215, for example ',(0,t.jsx)(a.code,{children:"SG215"})," under general surgery. It must be chosen from the specialty the patient is being treated under; if that specialty has none, none can be used. The procedure name and the amount are typed in by the hospital instead of coming from the plan. Check the amount on the server against the beneficiary's remaining limit, not only on the screen."]}),"\n",(0,t.jsxs)(a.p,{children:["An unspecified procedure is always planned, never an emergency. It always stands alone as a single line item, never combined with a normal package, an enhancement or an implant. It still needs a coverage eligibility check with purpose auth-requirements. There is no co-payment; PMJAY is fully cashless. In the bundle it is an ordinary claim item with product code ",(0,t.jsx)(a.code,{children:"U100"}),", the typed name as the display, and the typed amount as the price. Room type, if relevant, goes in the display text."]}),"\n",(0,t.jsx)(a.h2,{id:"cyclic-procedures",children:"Cyclic procedures"}),"\n",(0,t.jsx)(a.p,{children:"Dialysis is the model: one approval, many visits. The plan marks such packages as cyclic and says how many cycles one approval allows. The maximum is set by the state in the plan's claim conditions."}),"\n",(0,t.jsx)(a.p,{children:"Biometrics run through the whole thing. The patient is authenticated at the preauthorisation, again at every single visit with the process type set to Discharge, and again at the claim. Each visit needs a live capture; a refresh token is not accepted for a cycle, only for the final claim. Two cycles cannot be closer than 24 hours apart, counted as a rolling window, not a calendar day. A consent form cannot stand in for biometrics on a cyclic case."}),"\n",(0,t.jsx)(a.p,{children:"Payment follows the biometrics. Approval is for the maximum number of cycles, but the payer pays only for the cycles with a biometric capture. Four approved and two captured means two paid. Every cycle's clinical record travels as structured data, numbered in sequence and linked from the item, with a start and end time that the payer checks against the biometric timestamp; a mismatch voids the cycle. The claim is submitted once, after the last cycle. If the patient moves to another hospital, the first hospital is paid for its captured cycles and the patient is discharged; the new hospital raises a new preauthorisation."}),"\n",(0,t.jsx)(a.mermaid,{value:"sequenceDiagram\n  box rgb(220,239,227) Provider side\n    participant H as Hospital\n  end\n  box rgb(220,232,245) Payer side\n    participant Y as Payer\n  end\n  Note over H: live biometric, process type Preauth\n  H->>Y: preauthorisation for N cycles\n  Y--\x3e>H: approved for N\n  loop each visit, at least 24 hours apart\n    Note over H: live biometric, process type Discharge\n    H->>H: record the cycle with start and end time\n  end\n  Note over H: biometric or refresh token, process type Discharge\n  H->>Y: one claim, cycles as numbered structured records\n  Y--\x3e>H: paid for the cycles with a biometric capture"}),"\n",(0,t.jsx)(a.h2,{id:"medical-packages",children:"Medical packages"}),"\n",(0,t.jsx)(a.p,{children:"A medical package is treatment without surgery: medicines, therapy, monitoring. Two rules. Only one medical package can be claimed per episode. And a medical package cannot be combined with a surgical one, because surgical rates already include care before and after the operation. A patient admitted for a medical condition who then needs surgery is not booked under both."}),"\n",(0,t.jsx)(a.h2,{id:"newborns-and-children-up-to-six",children:"Newborns and children up to six"}),"\n",(0,t.jsxs)(a.p,{children:["A newborn has no card and no wallet of its own. The parent's card and wallet are used throughout, with the whole family sharing one annual limit. In the bundle the parent is the Patient; the child is a second, linked Patient resource with the child's name, gender and date of birth, referenced from the parent's record with link type ",(0,t.jsx)(a.code,{children:"refer"}),". Twins are two children and two separate preauthorisations."]}),"\n",(0,t.jsxs)(a.p,{children:["Proof of the child's date of birth is mandatory, filed under category ",(0,t.jsx)(a.code,{children:"DOB"})," with code ",(0,t.jsx)(a.code,{children:"BCF"})," for a birth certificate or ",(0,t.jsx)(a.code,{children:"DCB"})," for a government hospital's discharge slip while the certificate is awaited. The bill is in the parent's name as \"Baby of\" the parent, with a supporting attachment; a bill in the baby's name alone is likely to be rejected. A child older than a newborn but under six is treated as an ordinary case on the parent's wallet, without the linked-child construct."]}),"\n",(0,t.jsx)(a.h2,{id:"implants-and-stratification",children:"Implants and stratification"}),"\n",(0,t.jsx)(a.p,{children:"A package rate is a package rate. What the plan allows on top is spelled out per package as cost qualifiers: an implant such as a stent, a higher bed category, a high-end medicine or investigation. Each has its own code from the plan's master list, and each is a separate line in the bundle carrying the extra amount. The plan also says whether a package supports enhancement at all; a package that does not will have an enhancement rejected."})]})}function h(e={}){let{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,t.jsx)(a,{...e,children:(0,t.jsx)(d,{...e})}):d(e)}}}]);